1	// A tiny in-memory todo list.
2	export class TodoList {
3	  constructor() { this.items = []; this.nextId = 1; }
4	
5	  add(title) {
6	    if (!title) throw new Error("title is required");
7	    const item = { id: this.nextId++, title, done: false };
8	    this.items.push(item);
9	    return item;
10	  }
11	
12	  complete(id) {
13	    const item = this.items.find(i => i.id === id);
14	    if (!item) throw new Error(`item ${id} not found`);
15	    item.done = true;
16	    return item;
17	  }
18	
19	  pending() {
20	    return this.items.filter(i => !i.done);
21	  }
22	
23	  clear() {
24	    this.items = this.items.filter(i => !i.done);
25	  }
26	}
