1	import { test } from "node:test";
2	import assert from "node:assert/strict";
3	import { TodoList } from "../src/todo.js";
4	
5	test("ids are unique", () => {
6	  const list = new TodoList();
7	  const a = list.add("buy milk");
8	  const b = list.add("walk dog");
9	  assert.notEqual(a.id, b.id);
10	});
11	
12	test("pending lists only open items", () => {
13	  const list = new TodoList();
14	  const a = list.add("buy milk");
15	  list.add("walk dog");
16	  list.complete(a.id);
17	  assert.deepEqual(list.pending().map(i => i.title), ["walk dog"]);
18	});
19	
20	test("completing an unknown id throws", () => {
21	  const list = new TodoList();
22	  assert.throws(() => list.complete(42), /not found/);
23	});
24	
25	test("clear removes completed items", () => {
26	  const list = new TodoList();
27	  const a = list.add("buy milk");
28	  list.add("walk dog");
29	  list.complete(a.id);
30	  list.clear();
31	  assert.deepEqual(list.items.map(i => i.title), ["walk dog"]);
32	});
